update known_safe_harbors set tissue_context = 'Human iPSCs and neural stem cells (NSCs)' where source_pmid = '25587899' and evidence_summary = 'Direct CLYBL vs. AAVS1 comparison (founding paper for CLYBL as a safe harbor, TALEN, 38-58% efficiency): CLYBL gave STRONGER transgene expression and LESS disruption of local genes than PPP1R12C/AAVS1 in the same study, in human iPSCs and NSCs. Simultaneous dual knock-in at AAVS1 + CLYBL successfully demonstrated.';
