update known_safe_harbors set tissue_context = 'Structural/molecular biology study, not cell-type specific' where source_pmid = '1334463' and evidence_summary = 'Founding paper (1992): AAV integration occurs via non-homologous recombination, with direct repeats found at a frequency far above chance, distributed across the AAVS1 sequence. Presence of a CpG island with transcription-factor binding elements suggestive of a TATA-less promoter. Direct evidence of endogenous transcriptional activity in the region (RNA amplified by RT-PCR) -- helps explain why AAVS1 is permissive for transgene expression.';
