update known_safe_harbors set tissue_context = 'Human population genetics finding, not a specific cell type (natural allele carriers)' where source_pmid = '8756719' and evidence_summary = 'Founding paper (1996) discovering the CCR5-delta32 allele: individuals homozygous for the 32-base-pair deletion (truncated, cell-surface-undetectable protein) are resistant to primary HIV-1 entry. Crucial safety fact: "this defect has no obvious phenotype in affected individuals" -- they are healthy. Heterozygous carriers reach ~20% in some populations. The strongest natural human proof that losing CCR5 is well tolerated.';
update public_safe_harbors_staging set tissue_context = 'Human population genetics finding, not a specific cell type (natural allele carriers)' where source_pmid = '8756719' and evidence_summary = 'Founding paper (1996) discovering the CCR5-delta32 allele: individuals homozygous for the 32-base-pair deletion (truncated, cell-surface-undetectable protein) are resistant to primary HIV-1 entry. Crucial safety fact: "this defect has no obvious phenotype in affected individuals" -- they are healthy. Heterozygous carriers reach ~20% in some populations. The strongest natural human proof that losing CCR5 is well tolerated.';

update known_safe_harbors set tissue_context = 'Human population/clinical epidemiology finding, not a specific cell type' where source_pmid = '16418398' and evidence_summary = 'Important CORRECTION/NUANCE to the prior record on CCR5-delta32 "no phenotype": while it protects against HIV, CCR5-delta32 homozygosity is associated with a significantly INCREASED risk of symptomatic/fatal West Nile virus infection (odds ratio 4.4 in one cohort, 9.1 in another, both significant). Losing CCR5 is not "cost-free" -- it trades HIV resistance for greater vulnerability to a different specific viral infection. Important to qualify any therapeutic CCR5-targeting with this trade-off.';
update public_safe_harbors_staging set tissue_context = 'Human population/clinical epidemiology finding, not a specific cell type' where source_pmid = '16418398' and evidence_summary = 'Important CORRECTION/NUANCE to the prior record on CCR5-delta32 "no phenotype": while it protects against HIV, CCR5-delta32 homozygosity is associated with a significantly INCREASED risk of symptomatic/fatal West Nile virus infection (odds ratio 4.4 in one cohort, 9.1 in another, both significant). Losing CCR5 is not "cost-free" -- it trades HIV resistance for greater vulnerability to a different specific viral infection. Important to qualify any therapeutic CCR5-targeting with this trade-off.';

