update known_safe_harbors set tissue_context = 'Not locus-specific -- add-on regulatory element, inducible expression system context' where source_pmid = '40205378' and evidence_summary = 'Important correction to the prior A2UCOE record: a new limitation discovered -- in inducible systems, A2UCOE causes gene-expression "leakage" even without the inducer (doxycycline), regardless of the fragment length tested (547-1337bp). Solution found: inserting an SV40 poly-A terminator as a spacer between A2UCOE and the inducible promoter completely eliminates the leakage AND strengthens the anti-silencing effect by >60%, stable for at least 30 days.';
update public_safe_harbors_staging set tissue_context = 'Not locus-specific -- add-on regulatory element, inducible expression system context' where source_pmid = '40205378' and evidence_summary = 'Important correction to the prior A2UCOE record: a new limitation discovered -- in inducible systems, A2UCOE causes gene-expression "leakage" even without the inducer (doxycycline), regardless of the fragment length tested (547-1337bp). Solution found: inserting an SV40 poly-A terminator as a spacer between A2UCOE and the inducible promoter completely eliminates the leakage AND strengthens the anti-silencing effect by >60%, stable for at least 30 days.';

