update known_safe_harbors set tissue_context = 'Real human clinical case (bone marrow transplant), hematopoietic system' where source_pmid = '27942440' and evidence_summary = 'The most famous case of all, real clinical context (not experimental): the "Berlin patient" (Hutter et al. 2009) received a bone marrow transplant from a donor homozygous for CCR5-delta32 to treat leukemia -- became HIV-negative and remained free of detectable virus even after stopping antiretrovirals. Direct clinical proof that disabling CCR5 can control/cure HIV infection in humans, not just in a model.';
