update known_safe_harbors set tissue_context = 'General technical/vector-biology finding, not cell-type or locus specific' where source_pmid = '37100816' and evidence_summary = 'Linear DNA vectors with modified/blocked ends (including the CELiD type used in several AAVS1 records already catalogued) still integrate randomly into the genome in a substantial fraction of transfected cells (10-20%), even with blocked ends -- blocking the ends is not sufficient to prevent unwanted integration. Relevant for re-assessing the "extra safety" attributed to CELiD vectors in some earlier records.';
