update known_safe_harbors set tissue_context = 'General technical/genome-editing safety finding, not cell-type or locus specific' where source_pmid = '30010673' and evidence_summary = 'Safety finding relevant to any insertion at any safe harbor: repair of CRISPR-Cas9-induced double-strand breaks can cause large (multi-kb) deletions and complex genomic rearrangements directly at the target site itself -- not only at distant off-target sites. This was underestimated by earlier analyses focused only on the immediate vicinity of the cut. Relevant to any editing strategy at any of the loci already catalogued, regardless of how "safe" the locus is.';
